119	func buildComparisonCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
120		if len(call.Args) != 2 {
121			return nil, errors.New("comparison expects two arguments")
122		}
123		op, err := toComparisonOperator(call.Function)
124		if err != nil {
125			return nil, err
126		}
127	
128		left, err := buildValueExpr(call.Args[0], pc)
129		if err != nil {
130			return nil, err
131		}
132		right, err := buildValueExpr(call.Args[1], pc)
133		if err != nil {
134			return nil, err
135		}
136	
137		// The renderer expects a field/function/accessor on the left. A folded
138		// literal on the left (e.g. now.getMonth() == created_ts.getMonth()) swaps
139		// operands; two literals fold to a constant outcome.
140		if leftLit, ok := left.(*LiteralValue); ok {
141			if rightLit, ok := right.(*LiteralValue); ok {
142				outcome, err := compareLiterals(leftLit.Value, op, rightLit.Value)
143				if err != nil {
144					return nil, err
145				}
146				return &ConstantCondition{Value: outcome}, nil
147			}
148			left, right = right, left
149			op = mirrorComparisonOperator(op)
150		}
151	
152		// If the left side is a field, validate allowed operators.
153		if field, ok := left.(*FieldRef); ok {
154			def, exists := pc.schema.Field(field.Name)
155			if !exists {
156				return nil, errors.Errorf("unknown identifier %q", field.Name)
157			}
158			if def.Kind == FieldKindVirtualAlias {
159				def, exists = pc.schema.ResolveAlias(field.Name)
160				if !exists {
161					return nil, errors.Errorf("invalid alias %q", field.Name)
162				}
163			}
164			if def.AllowedComparisonOps != nil {
165				if _, allowed := def.AllowedComparisonOps[op]; !allowed {
166					return nil, errors.Errorf("operator %s not allowed for field %q", op, field.Name)
167				}
168			}
169		}
170	
171		return &ComparisonCondition{
172			Left:     left,
173			Operator: op,
174			Right:    right,
175		}, nil
176	}
177	
178	// mirrorComparisonOperator flips an operator so swapped operands keep the
179	// original meaning (a < b ⇔ b > a).
